import math

def is_power_of_3(n):
    if n <= 0:
        return False
    if n == 1:
        return True

    # Check if the number is divisible by 3 repeatedly until it's 1 or not divisible
    while n > 1 and n % 3 == 0:
        n //= 3
    return n == 1

def solve_diophantine_system(j, n):
    # j <= n must hold
    if j > n:
        return None

    # Equation 1: 9j^2 + n = 3^(x-2)
    LHS1 = 9 * j**2 + n
    if LHS1 <= 0:
        return None
    if not is_power_of_3(LHS1):
        return None

    # Equation 2: 9n^2 + j = 3^(y-2)
    LHS2 = 9 * n**2 + j
    if LHS2 <= 0:
        return None
    if not is_power_of_3(LHS2):
        return None

    # If both are powers of 3, we found a solution (j, n, x, y)
    # x-2 = log3(LHS1), y-2 = log3(LHS2)
    x = int(math.log(LHS1, 3)) + 2
    y = int(math.log(LHS2, 3)) + 2

    return (j, n, x, y)

# Test cases for j=2 and j=4
j_values = [2, 4]
# Iterate n up to 10*j, as the powers of 3 grow very fast, limiting the search space
results = {}
for j in j_values:
    results[j] = []
    # Since 9j^2 + n = 3^(x-2), n < 3^(x-2). 
    # If x-2 = 4 (min possible power > 9j^2), n is bounded.
    # For j=2, 9j^2=36. 3^5=243. n < 207.
    # For j=4, 9j^2=144. 3^5=243. n < 100.

    # We search n up to 100 based on early estimates, but the actual bound is much tighter due to LHS2 growing quadratically in n.
    # Let's search n up to 100 for j=4 and up to 500 for j=2, as an initial check.
    n_limit = 500 if j == 2 else 100 

    for n in range(j, n_limit + 1):
        solution = solve_diophantine_system(j, n)
        if solution:
            results[j].append(solution)

print(results)
